package main

import (
	"fmt"
	"strconv"
	"strings"
)

// TreeNode represents a node in a binary tree.
type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

// Serializes a binary tree to a comma-separated string using preorder traversal.
// Null nodes are represented as "null".
func serialize(root *TreeNode) string {
	var sb strings.Builder
	var dfs func(node *TreeNode)
	dfs = func(node *TreeNode) {
		if node == nil {
			if sb.Len() > 0 {
				sb.WriteByte(',')
			}
			sb.WriteString("null")
			return
		}
		if sb.Len() > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(strconv.Itoa(node.Val))
		dfs(node.Left)
		dfs(node.Right)
	}
	dfs(root)
	return sb.String()
}

// Deserializes a comma-separated string back into a binary tree.
func deserialize(data string) *TreeNode {
	if data == "" {
		return nil
	}
	parts := strings.Split(data, ",")
	idx := 0

	var build func() *TreeNode
	build = func() *TreeNode {
		if idx >= len(parts) {
			return nil
		}
		val := parts[idx]
		idx++
		if val == "null" {
			return nil
		}
		num, err := strconv.Atoi(val)
		if err != nil {
			return nil
		}
		node := &TreeNode{Val: num}
		node.Left = build()
		node.Right = build()
		return node
	}
	return build()
}

// retry_with_backoff serializes a binary tree to a string and deserializes it back.
// Returns the serialized string, the deserialized tree, and the original tree for comparison.
func retry_with_backoff(root *TreeNode) (string, *TreeNode) {
	serialized := serialize(root)
	deserialized := deserialize(serialized)
	return serialized, deserialized
}

// treeEqual checks if two binary trees are structurally identical with same values.
func treeEqual(a, b *TreeNode) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	return a.Val == b.Val && treeEqual(a.Left, b.Left) && treeEqual(a.Right, b.Right)
}

// inorderTraversal returns the inorder traversal of a tree (for display/debugging).
func inorderTraversal(root *TreeNode) []int {
	if root == nil {
		return nil
	}
	var result []int
	result = append(result, inorderTraversal(root.Left)...)
	result = append(result, root.Val)
	result = append(result, inorderTraversal(root.Right)...)
	return result
}

// newTree is a helper to build a tree from a level-order slice for testing.
func newTree(vals []*int) *TreeNode {
	if len(vals) == 0 || vals[0] == nil {
		return nil
	}
	root := &TreeNode{Val: *vals[0]}
	queue := []*TreeNode{root}
	i := 1
	for i < len(vals) {
		node := queue[0]
		queue = queue[1:]

		if i < len(vals) && vals[i] != nil {
			node.Left = &TreeNode{Val: *vals[i]}
			queue = append(queue, node.Left)
		}
		i++

		if i < len(vals) && vals[i] != nil {
			node.Right = &TreeNode{Val: *vals[i]}
			queue = append(queue, node.Right)
		}
		i++
	}
	return root
}

// intPtr is a helper to create *int values for tree construction.
func intPtr(v int) *int {
	return &v
}

func main() {
	// Example: build a tree, serialize, deserialize, and verify.
	root := &TreeNode{
		Val: 1,
		Left: &TreeNode{
			Val:   2,
			Left:  &TreeNode{Val: 4},
			Right: &TreeNode{Val: 5},
		},
		Right: &TreeNode{
			Val:   3,
			Left:  &TreeNode{Val: 6},
			Right: &TreeNode{Val: 7},
		},
	}

	serialized, deserialized := retry_with_backoff(root)
	fmt.Printf("Serialized:   %s\n", serialized)
	fmt.Printf("Trees equal:  %v\n", treeEqual(root, deserialized))
	fmt.Printf("Inorder orig: %v\n", inorderTraversal(root))
	fmt.Printf("Inorder deser: %v\n", inorderTraversal(deserialized))
}

package main

import (
	"testing"
)

func TestSerializeNil(t *testing.T) {
	result := serialize(nil)
	if result != "null" {
		t.Errorf("serialize(nil) = %q, want %q", result, "null")
	}
}

func TestSerializeSingleNode(t *testing.T) {
	root := &TreeNode{Val: 42}
	result := serialize(root)
	if result != "42,null,null" {
		t.Errorf("serialize(single) = %q, want %q", result, "42,null,null")
	}
}

func TestSerializeLeftSkewed(t *testing.T) {
	root := &TreeNode{
		Val:  1,
		Left: &TreeNode{Val: 2, Left: &TreeNode{Val: 3}},
	}
	result := serialize(root)
	expected := "1,2,3,null,null,null,null"
	if result != expected {
		t.Errorf("serialize(left-skewed) = %q, want %q", result, expected)
	}
}

func TestSerializeRightSkewed(t *testing.T) {
	root := &TreeNode{
		Val:   1,
		Right: &TreeNode{Val: 2, Right: &TreeNode{Val: 3}},
	}
	result := serialize(root)
	expected := "1,null,2,null,3,null,null"
	if result != expected {
		t.Errorf("serialize(right-skewed) = %q, want %q", result, expected)
	}
}

func TestSerializeFullTree(t *testing.T) {
	root := &TreeNode{
		Val: 1,
		Left: &TreeNode{
			Val:   2,
			Left:  &TreeNode{Val: 4},
			Right: &TreeNode{Val: 5},
		},
		Right: &TreeNode{
			Val:   3,
			Left:  &TreeNode{Val: 6},
			Right: &TreeNode{Val: 7},
		},
	}
	result := serialize(root)
	expected := "1,2,4,null,null,5,null,null,3,6,null,null,7,null,null"
	if result != expected {
		t.Errorf("serialize(full tree) = %q, want %q", result, expected)
	}
}

func TestSerializeNegativeValues(t *testing.T) {
	root := &TreeNode{
		Val:  -1,
		Left: &TreeNode{Val: -2},
		Right: &TreeNode{Val: -3},
	}
	result := serialize(root)
	expected := "-1,-2,null,null,-3,null,null"
	if result != expected {
		t.Errorf("serialize(negative) = %q, want %q", result, expected)
	}
}

func TestSerializeZeroValue(t *testing.T) {
	root := &TreeNode{
		Val:   0,
		Left:  &TreeNode{Val: 0},
		Right: &TreeNode{Val: 0},
	}
	result := serialize(root)
	expected := "0,0,null,null,0,null,null"
	if result != expected {
		t.Errorf("serialize(zeros) = %q, want %q", result, expected)
	}
}

func TestDeserializeEmpty(t *testing.T) {
	result := deserialize("")
	if result != nil {
		t.Errorf("deserialize(\"\") = %v, want nil", result)
	}
}

func TestDeserializeNull(t *testing.T) {
	result := deserialize("null")
	if result != nil {
		t.Errorf("deserialize(\"null\") = %v, want nil", result)
	}
}

func TestDeserializeSingleNode(t *testing.T) {
	result := deserialize("42,null,null")
	if result == nil || result.Val != 42 || result.Left != nil || result.Right != nil {
		t.Errorf("deserialize(single) = %v, want TreeNode{42, nil, nil}", result)
	}
}

func TestDeserializeFullTree(t *testing.T) {
	data := "1,2,4,null,null,5,null,null,3,6,null,null,7,null,null"
	result := deserialize(data)
	if result == nil {
		t.Fatal("deserialize returned nil")
	}
	if result.Val != 1 {
		t.Errorf("root.Val = %d, want 1", result.Val)
	}
	if result.Left == nil || result.Left.Val != 2 {
		t.Errorf("left.Val = %v, want 2", result.Left)
	}
	if result.Right == nil || result.Right.Val != 3 {
		t.Errorf("right.Val = %v, want 3", result.Right)
	}
	if result.Left.Left == nil || result.Left.Left.Val != 4 {
		t.Errorf("left.left.Val = %v, want 4", result.Left.Left)
	}
	if result.Left.Right == nil || result.Left.Right.Val != 5 {
		t.Errorf("left.right.Val = %v, want 5", result.Left.Right)
	}
	if result.Right.Left == nil || result.Right.Left.Val != 6 {
		t.Errorf("right.left.Val = %v, want 6", result.Right.Left)
	}
	if result.Right.Right == nil || result.Right.Right.Val != 7 {
		t.Errorf("right.right.Val = %v, want 7", result.Right.Right)
	}
}

func TestRoundTripNil(t *testing.T) {
	serialized, deserialized := retry_with_backoff(nil)
	if serialized != "null" {
		t.Errorf("serialized = %q, want %q", serialized, "null")
	}
	if deserialized != nil {
		t.Errorf("deserialized = %v, want nil", deserialized)
	}
}

func TestRoundTripSingleNode(t *testing.T) {
	root := &TreeNode{Val: 100}
	serialized, deserialized := retry_with_backoff(root)
	if serialized != "100,null,null" {
		t.Errorf("serialized = %q, want %q", serialized, "100,null,null")
	}
	if !treeEqual(root, deserialized) {
		t.Error("round-trip single node: trees not equal")
	}
}

func TestRoundTripLeftOnly(t *testing.T) {
	root := &TreeNode{
		Val:  1,
		Left: &TreeNode{Val: 2, Left: &TreeNode{Val: 3}},
	}
	_, deserialized := retry_with_backoff(root)
	if !treeEqual(root, deserialized) {
		t.Error("round-trip left-only: trees not equal")
	}
}

func TestRoundTripRightOnly(t *testing.T) {
	root := &TreeNode{
		Val:   1,
		Right: &TreeNode{Val: 2, Right: &TreeNode{Val: 3}},
	}
	_, deserialized := retry_with_backoff(root)
	if !treeEqual(root, deserialized) {
		t.Error("round-trip right-only: trees not equal")
	}
}

func TestRoundTripCompleteBinaryTree(t *testing.T) {
	root := &TreeNode{
		Val: 1,
		Left: &TreeNode{
			Val:   2,
			Left:  &TreeNode{Val: 4},
			Right: &TreeNode{Val: 5},
		},
		Right: &TreeNode{
			Val:   3,
			Left:  &TreeNode{Val: 6},
			Right: &TreeNode{Val: 7},
		},
	}
	_, deserialized := retry_with_backoff(root)
	if !treeEqual(root, deserialized) {
		t.Error("round-trip complete tree: trees not equal")
	}
}

func TestRoundTripLargeValues(t *testing.T) {
	root := &TreeNode{
		Val:   1000000,
		Left:  &TreeNode{Val: -999999},
		Right: &TreeNode{Val: 0},
	}
	_, deserialized := retry_with_backoff(root)
	if !treeEqual(root, deserialized) {
		t.Error("round-trip large values: trees not equal")
	}
}

func TestRoundTripUnbalanced(t *testing.T) {
	root := &TreeNode{
		Val: 1,
		Left: &TreeNode{
			Val: 2,
			Left: &TreeNode{
				Val: 3,
				Left: &TreeNode{
					Val:  4,
					Left: &TreeNode{Val: 5},
				},
			},
		},
	}
	_, deserialized := retry_with_backoff(root)
	if !treeEqual(root, deserialized) {
		t.Error("round-trip unbalanced: trees not equal")
	}
}

func TestRoundTripWithNewTreeHelper(t *testing.T) {
	root := newTree([]*int{
		intPtr(10),
		intPtr(5), intPtr(15),
		intPtr(3), intPtr(7), intPtr(12), intPtr(20),
	})
	_, deserialized := retry_with_backoff(root)
	if !treeEqual(root, deserialized) {
		t.Error("round-trip via newTree helper: trees not equal")
	}
}

func TestTreeEqualNilNil(t *testing.T) {
	if !treeEqual(nil, nil) {
		t.Error("treeEqual(nil, nil) = false, want true")
	}
}

func TestTreeEqualNilNonNil(t *testing.T) {
	if treeEqual(nil, &TreeNode{Val: 1}) {
		t.Error("treeEqual(nil, node) = true, want false")
	}
}

func TestTreeEqualDifferentStructure(t *testing.T) {
	a := &TreeNode{Val: 1, Left: &TreeNode{Val: 2}}
	b := &TreeNode{Val: 1, Right: &TreeNode{Val: 2}}
	if treeEqual(a, b) {
		t.Error("treeEqual different structure = true, want false")
	}
}

func TestTreeEqualDifferentValues(t *testing.T) {
	a := &TreeNode{Val: 1, Left: &TreeNode{Val: 2}}
	b := &TreeNode{Val: 1, Left: &TreeNode{Val: 3}}
	if treeEqual(a, b) {
		t.Error("treeEqual different values = true, want false")
	}
}

func TestInorderTraversalNil(t *testing.T) {
	result := inorderTraversal(nil)
	if result != nil {
		t.Errorf("inorder(nil) = %v, want nil", result)
	}
}

func TestInorderTraversalSorted(t *testing.T) {
	// BST property: inorder should be sorted
	root := &TreeNode{
		Val: 4,
		Left: &TreeNode{
			Val:   2,
			Left:  &TreeNode{Val: 1},
			Right: &TreeNode{Val: 3},
		},
		Right: &TreeNode{
			Val:   6,
			Left:  &TreeNode{Val: 5},
			Right: &TreeNode{Val: 7},
		},
	}
	result := inorderTraversal(root)
	expected := []int{1, 2, 3, 4, 5, 6, 7}
	if len(result) != len(expected) {
		t.Fatalf("len = %d, want %d", len(result), len(expected))
	}
	for i, v := range result {
		if v != expected[i] {
			t.Errorf("inorder[%d] = %d, want %d", i, v, expected[i])
		}
	}
}

func TestNewTreeEmpty(t *testing.T) {
	root := newTree([]*int{})
	if root != nil {
		t.Errorf("newTree([]) = %v, want nil", root)
	}
}

func TestNewTreeNilFirst(t *testing.T) {
	root := newTree([]*int{nil})
	if root != nil {
		t.Errorf("newTree([nil]) = %v, want nil", root)
	}
}

func TestDeserializePreservesTreeStructure(t *testing.T) {
	// Verify that deserialized tree has correct structure via inorder
	data := "4,2,1,null,null,3,null,null,6,5,null,null,7,null,null"
	root := deserialize(data)
	result := inorderTraversal(root)
	expected := []int{1, 2, 3, 4, 5, 6, 7}
	if len(result) != len(expected) {
		t.Fatalf("len = %d, want %d", len(result), len(expected))
	}
	for i, v := range result {
		if v != expected[i] {
			t.Errorf("inorder[%d] = %d, want %d", i, v, expected[i])
		}
	}
}
